const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
(async()=>{const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1500,height:1000}}),errors=[],network=[];page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(/^https?:/.test(r.url()))network.push(r.url())});await page.goto('file://'+path.join(__dirname,'index.html'));
await page.locator('#folder').setInputFiles(process.env.LOG_FOLDER);await page.locator('#workspace').waitFor({state:'visible'});assert.match(await page.locator('#metrics').innerText(),/27/);assert.equal(await page.locator('.request').count(),27);
await page.locator('#search').fill('_24_2');await page.locator('.request').click();await page.waitForFunction(()=>document.querySelector('#shot').naturalWidth>0);assert.match(await page.locator('#detail').innerText(),/发起视频前无法确认当前联系人是女儿/);assert.equal(await page.locator('#box').isVisible(),true);
await page.locator('[data-tab="output"]').click();assert.match(await page.locator('#detail').innerText(),/0.93/);
await page.locator('[data-tab="tree"]').click();await page.getByLabel('筛选 UI Tree 节点').fill('女儿');assert.match(await page.locator('#detail table').innerText(),/女儿/);await page.locator('#detail table tr').nth(1).click();
await page.locator('[data-tab="overview"]').click();await page.screenshot({path:path.join(__dirname,'preview.png'),fullPage:false});
await page.locator('#runEvents').click();assert.match(await page.locator('#detail').innerText(),/STOPPED/);
await page.locator('#clear').click();assert.equal(await page.locator('#workspace').isVisible(),false);assert.equal(await page.locator('#shot').getAttribute('src'),null);
const hostile='<img src=x onerror="window.PWNED=1">';const fake=[{session_id:'sample',event:'request',data:{request_id:'r',step:1,attempt:1,screenshot_ref:'missing.jpg'}},{session_id:'sample',event:'guidance',data:{request_id:'r',instruction:hostile}}].map(JSON.stringify).join('\n')+'\nBROKEN';
await page.locator('#files').setInputFiles({name:'events.jsonl',mimeType:'application/json',buffer:Buffer.from(fake)});await page.locator('#workspace').waitFor({state:'visible'});assert.equal(await page.locator('#warnings').isVisible(),true);assert.match(await page.locator('#imageinfo').innerText(),/缺少附件/);assert.match(await page.locator('#detail').innerText(),/onerror/);assert.equal(await page.evaluate(()=>window.PWNED),undefined);assert.equal(await page.locator('#detail img').count(),0);
await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),true);
assert.deepEqual(errors,[]);assert.deepEqual(network,[]);console.log('PASS: real-folder import, 27 request associations, request search, model output, UI Tree node selection, image + target box, run events, clear/revoke, malformed-line warning, missing attachment, untrusted text rendering, mobile width, zero external requests.');}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
